<template><main class="admin-content"><AdminSalesWorkflow /><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="kc-eyebrow">Sales</p><h1 class="text-3xl font-black text-slate-900">Customers</h1><p class="text-slate-500">Reusable customer profiles for manual quotes. Link registered login accounts to customer profiles.</p></div><button class="btn-primary" @click="newCustomer">+ Add Customer</button></div><div v-if="msg" class="mb-4 kc-alert-success">{{msg}}</div><div v-if="err" class="mb-4 kc-alert-error">{{err}}</div><section class="admin-panel p-4"><input v-model="search" class="input" placeholder="Search name, company, email or phone" @input="load"/></section><section class="mt-5 grid gap-4 lg:grid-cols-2"><article v-for="c in customers" :key="c.id" class="admin-panel p-5" :class="c.login_only ? 'border-amber-300 bg-amber-50/30' : ''"><div class="flex justify-between gap-3"><div><h2 class="font-black text-slate-900">{{c.full_name}}</h2><p v-if="c.company_name" class="font-semibold text-blue-600">{{c.company_name}}</p><p class="text-sm text-slate-500">{{c.email||'No email'}} · {{c.phone||'No phone'}}</p></div><button v-if="!c.login_only" class="btn-secondary" @click="edit(c)">Edit</button><button v-else class="btn-primary" @click="createCustomerProfile(c)">Create / Link Customer</button></div><div class="mt-3 flex flex-wrap items-center gap-2"><span v-if="c.login_only" class="rounded-full bg-amber-100 px-2.5 py-1 text-xs font-bold text-amber-800">Login Account Only</span><span v-else-if="c.auth_user_id" class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700">Linked Login</span><span class="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700">Price Level: {{pricingLevelName(c.pricing_level_key)}}</span><span class="text-xs text-slate-500">{{c.manual_quotes?.length||0}} quote(s)</span><span class="rounded-full px-2.5 py-1 text-xs font-bold" :class="c.processing_fee_enabled === false ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-700'">Processing Fee: {{ c.processing_fee_enabled === false ? 'Off' : 'On' }}</span></div><div v-if="!c.login_only" class="mt-3 flex gap-2"><button class="btn-primary" @click="createQuote(c.id)">New Quote</button></div></article></section>
<div v-if="form" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="form=null"><form class="max-h-[90vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-6" @submit.prevent="save"><div class="flex justify-between"><h2 class="text-xl font-black">{{form.id?'Edit':'Add'}} Customer</h2><button type="button" @click="form=null">✕</button></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label><span class="label">Type</span><select v-model="form.customer_type" class="input"><option value="individual">Individual</option><option value="business">Business</option></select></label><label><span class="label">Pricing Level</span><select v-model="form.pricing_level_key" class="input"><option v-for="p in pricingLevels" :key="p.key" :value="p.key">{{p.name}} ({{p.markup_percent}}%)</option></select></label><label><span class="label">Full Name *</span><input v-model="form.full_name" class="input" required></label><label><span class="label">Company</span><input v-model="form.company_name" class="input"></label><label><span class="label">Email</span><input v-model="form.email" type="email" class="input"></label><label><span class="label">Phone</span><input v-model="form.phone" class="input"></label></div><label class="mt-4 block"><span class="label">Login Account</span><select v-model="form.auth_user_id" class="input"><option value="">Not linked</option><option v-for="u in loginUsers" :key="u.id" :value="u.id">{{u.email}} {{u.full_name ? `— ${u.full_name}` : ""}}</option></select></label><label class="mt-4 flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3"><input v-model="form.processing_fee_enabled" type="checkbox" class="h-4 w-4"><span><span class="block font-bold text-slate-800">Charge Processing Fee</span><span class="text-sm text-slate-500">On by default. Turn this off to waive the processing fee for this customer.</span></span></label><label class="mt-4 block"><span class="label">Billing Address</span><textarea v-model="form.billing_address" class="input" rows="3"/></label><label class="mt-4 block"><span class="label">Delivery Address</span><textarea v-model="form.delivery_address" class="input" rows="3"/></label><label class="mt-4 block"><span class="label">Internal Notes</span><textarea v-model="form.notes" class="input" rows="3"/></label><div class="mt-5 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="form=null">Cancel</button><button class="btn-primary">Save Customer</button></div></form></div></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch();const customers=ref<any[]>([]),pricingLevels=ref<any[]>([]),loginUsers=ref<any[]>([]),search=ref(''),form=ref<any>(null),msg=ref(''),err=ref('');let timer:any;async function load(){clearTimeout(timer);timer=setTimeout(async()=>{try{customers.value=await adminFetch(`/api/admin/customers?search=${encodeURIComponent(search.value)}`) as any[]}catch(e:any){err.value=e?.data?.statusMessage||e.message}},200)}function newCustomer(){form.value={customer_type:'individual',pricing_level_key:'standard',full_name:'',company_name:'',email:'',phone:'',billing_address:'',delivery_address:'',notes:'',auth_user_id:'',processing_fee_enabled:true}}function edit(c:any){form.value={...c,processing_fee_enabled:c.processing_fee_enabled !== false}}function pricingLevelName(key:string){return pricingLevels.value.find((p:any)=>p.key===key)?.name||key||'Standard'}async function save(){try{const f=form.value;await adminFetch(f.id?`/api/admin/customers/${f.id}`:'/api/admin/customers',{method:f.id?'PUT':'POST',body:f});msg.value='Customer saved.';form.value=null;await load()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function createCustomerProfile(c:any){try{err.value='';await adminFetch('/api/admin/customers/link-login',{method:'POST',body:{auth_user_id:c.auth_user_id}});msg.value='Login account linked to a customer profile.';await load();loginUsers.value=await adminFetch('/api/admin/customer-login-users') as any[]}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function createQuote(customer_id:string){const q:any=await adminFetch('/api/admin/manual-quotes',{method:'POST',body:{customer_id}});await navigateTo(`/admin/manual-quotes/${q.id}`)}onMounted(async()=>{try{pricingLevels.value=await adminFetch('/api/admin/pricing-levels') as any[]}catch{}try{loginUsers.value=await adminFetch('/api/admin/customer-login-users') as any[]}catch{}await load()})</script>
<style scoped>.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm}.label{@apply mb-1 block text-sm font-bold text-slate-700}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-blue-700}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50}.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}</style>
